package com.ryanjei.orushio.pve.paper;
import static org.junit.jupiter.api.Assertions.*;import com.ryanjei.orushio.pve.map.*;import java.util.*;import org.junit.jupiter.api.Test;
class PaperGameRuntimeGatewayTest{
 @Test void runWorldへWarpとSavePointだけを可視化する(){MapProfile base=MapProfileTest.complete("map-a");BlockPoint warp=new BlockPoint(10,64,10,0,0),save=new BlockPoint(20,64,20,0,0),gate=new BlockPoint(30,64,30,0,0),disabled=new BlockPoint(40,64,40,0,0);List<SetupMarker>markers=new ArrayList<>(base.setupMarkers());markers.add(new SetupMarker(UUID.randomUUID(),SetupMarkerType.WARP,warp,true));markers.add(new SetupMarker(UUID.randomUUID(),SetupMarkerType.SAVE_POINT,save,true));markers.add(new SetupMarker(UUID.randomUUID(),SetupMarkerType.FINAL_GATE,gate,true));markers.add(new SetupMarker(UUID.randomUUID(),SetupMarkerType.WARP,disabled,false));MapProfile profile=new MapProfile(base.mapId(),base.displayName(),base.enabled(),base.templateDirectory(),base.points(),base.areas(),base.createdAt(),base.spawnMarkers(),markers);Map<BlockPoint,String>blocks=PaperGameRuntimeGateway.gameplayMarkerBlocks(profile);assertEquals(PaperMapWorldGateway.materialName(SetupMarkerType.WARP),blocks.get(warp));assertEquals(PaperMapWorldGateway.materialName(SetupMarkerType.SAVE_POINT),blocks.get(save));assertFalse(blocks.containsKey(gate));assertFalse(blocks.containsKey(disabled));}
}
